architecture.h4_f:
msg = CBOR{v:1, text, reply_to, sent_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, text, odpovedať_na?, vlákno_id?, zmienky?, odoslaný_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
drôt = CBOR{
  v: 1,
  ciphertext: hex(ct), // premenlivá dĺžka
  nonce: hex(12 B),
  sender_pseudo: hex(16 B),
  odoslané_at: unix_ms
}

cryptoWire.h5_f:
vonkajšie = CBOR{
  source_node: hex32,
  target_user: int64,
  inner_ciphertext: bytes,
  inner_nonce: bytes,
  odoslané_at: unix_ms
}
sig = Ed25519-Sign(source_priv, external)
POST /federation/deliver { obálka: vonkajšia, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { username, password, x25519_public_key, display_name, phone?, email?, avatar_emoji }

Odpoveď 201 vytvorená:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
Užitočné zaťaženie prístupového_tokenu:
  { sub: user_id, jti: device_id, typ: "access", exp: now + 15min }
refresh_token užitočné zaťaženie:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256-podpísané 64-bajtovým tajomstvom uzla z .env

auth.h4_f:
register_begin(): výzva = rand(32)
                    options = { rp.id, user.id, pubKeyCredParams, challenge }
                    možnosti vrátenia

register_finish(atestácia):
  overiť atestáciu proti TPM / Secure Enclave root CA
  store { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR užitočné zaťaženie = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → nové zariadenie zaregistrované; JWT sa vrátili.

rooms.h6_f:
odosielateľ_pseudo = HMAC-SHA256(miestna_pseudo_soľ, identifikátor_odosielateľa)[:16] // 32 hex
ciphertext = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Rozvetvený rám: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {filename, size, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bajtov>
            ← 204
finalize POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL nedokončené: 24 h

files.h4_f:
deny_list = {
  "aplikácia/x-dosexec",
  "application/x-sharedlib",
  "aplikácia/x-mach-binary",
}
if magic.from_buffer(buf[:1024]) v deny_list: return 415

presence.h1_f:
klient: pri prvom stlačení klávesu → odoslať {type:"t", state:"start"}
         žiadne ďalšie odosielanie po dobu 3 s, pokiaľ sa stav nezmení
         10 s po poslednom stlačení klávesu → odoslať {type:"t", state:"stop"}
prijímač: automatické zastavenie 10 s po poslednom "štarte", ak neprišlo žiadne "stop".

presence.h2_f:
POST /api/rooms/{id}/read { last_read_message_id }

if user.hides_receipts:
   nepretrvávajú; nevysielať
   nepodávajte tomuto používateľovi potvrdenky iných používateľov
inak:
   UPSERT read_receipts VALUES (room_id, user_id, message_id, NOW())
   vysielanie {type:"r", room, user, message_id}

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS vysielanie {type:"c", kind:"invite", call_id}
WS vysielanie {type:"c", kind:"offer", sdp}
WS vysielanie {type:"c", kind:"answer", sdp}
WS vysielanie {type:"c", druh:"candidate",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
obálka = {
  source_node : hex32,
  cieľový_používateľ: int64,
  inner_ciphertext: bytes,
  inner_nonce : bytes,
  send_at: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(obálka))
POST /federation/deliver { obálka, podpis }

gossip.h3_f:
reklama = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(reklama))
užitočný obsah klebiet: [..., {ad, sig}, ...]

prijímač: overte sig proti ad.pubkey → uložiť, ak je to v poriadku
ďalšie: PoW 2^18 vedúcich núl na {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template s {
  náhodný = náš náhodný,
  server_name = názov nášho hostiteľa (alebo zabalené ECH),
  session_id = naše ID relácie,
}
JA4 = t13d_xxxx_xxxx_xxxx   (matches current Chrome stable)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {name: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: doména(t) = základ32( SHA256(prvok ∥ YYYY-MM-DD) )[:16] + ".príklad"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
tool = sign_tool
input = zdrojový strom, kľúče/uvoľnenie.kľúč
manifest = {
  verzia: "0.1.0",
  built_at: unix_ms,
  súbory: [{cesta, sha256, veľkosť}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
output = INTEGRITY.sig.json = {manifest, sign_by: pub_hex, sig: sig_hex}

bots.h1_f:
vytvoriť: POST /api/bots {username, display_name, code}
          → {bot_id, token, pubkey}
beh: prebieha (korutín vo vnútri uzla)
      OR externé (long-prill /api/bots/{id}/updates, token-auth'd)
správa: {text, podpis: Ed25519-Sign(bot_priv, canonical_msg)}

